/* Upgrade Quote Sheet — customer-view art (2026-09-27).
   The hero art, the xfinity wordmark and the footer ribbon, byte-for-byte the base64 images that
   used to be inlined in index.html (109 KB of its 229 KB gzipped). The cookcountycooks.com viewer
   re-downloads index.html on EVERY open (?_ccc=<time>), but this file is cached like any script,
   so a rep on store Wi-Fi no longer pays for the art on every open. index.html loads it once the
   page is up and puts the images back exactly where they were (xfApplyArt), so the customer view,
   Print and Email PDF see the very same data: URLs as before.
   Upload this file next to index.html in the Upgrade-Quote-Sheet repo. */
window.XF_ART = {
 hero: "data:image/webp;base64,",
 wordmark: "data:image/webp;base64,",
 ribbon: "data:image/webp;base64,"
};
